// Connect to MongoDB and load the database into memory.
// Must be awaited once at server startup, before app.listen().
async function connectDB() {
  if (!MONGODB_URI) {
    throw new Error(
      "MONGODB_URI environment variable is not set. Add it in Render > Environment."
    );
  }

  mongoClient = new MongoClient(MONGODB_URI, {
    // Auto-retry a write/read that failed only because of a transient
    // network blip or replica-set failover, instead of surfacing it as a
    // hard error on the very first hiccup.
    retryWrites: true,
    retryReads: true,
    // Don't hang forever if Mongo is briefly unreachable — fail fast so
    // the request handler's existing try/catch can log it and move on.
    serverSelectionTimeoutMS: 10000,
    maxPoolSize: 20,
  });
  mongoClient.on("error", (err) => {
    console.error("MongoDB client error:", err.message);
  });
  await mongoClient.connect();
  const db = mongoClient.db(DB_NAME);
  mongoCollection = db.collection(COLLECTION_NAME);
  productsStore.init(db);

  const existing = await mongoCollection.findOne({ _id: DOC_ID });

  if (existing) {
    delete existing._id;
    cachedData = existing;
    console.log("Design Makers database loaded from MongoDB.");

    // ONE-TIME AUTO-MIGRATION: older app_data documents still carry an
    // embedded `products` array. If we find one, move it into the
    // dedicated `products` collection (via products-store.js) and strip
    // it out of app_data from now on — this is exactly what was causing
    // app_data to blow past MongoDB's 16MB document limit as the catalog
    // (and its base64 product photos) grew. Runs automatically, every
    // deploy, and is a safe no-op once already migrated.
    if (Array.isArray(existing.products) && existing.products.length > 0) {
      const migratedCount = await productsStore.migrateLegacyProducts(existing.products);
      delete cachedData.products;
      await mongoCollection.updateOne({ _id: DOC_ID }, { $unset: { products: "" } });
      console.log(
        `One-time migration: moved ${migratedCount} product(s) out of app_data into their own 'products' collection.`
      );
    }
  } else {
    // SAFETY NET: previously, a missing document here silently triggered
    // creating a brand-new database from `defaultDatabase` (the hardcoded
    // sample products). That's exactly what happens if MONGODB_URI ever
    // points somewhere new/wrong (bad env var, wrong cluster) after the
    // site has been live for a while — the app would quietly "reset" to
    // only the code's sample data, making it look like every admin-added
    // product vanished, even though the real data was untouched and just
    // sitting in the old database, now orphaned.
    //
    // Now this fails loudly instead of failing silently: unless someone
    // explicitly confirms this is a brand-new site (ALLOW_NEW_DATABASE=true),
    // the server refuses to start and logs exactly why. A misconfigured
    // MONGODB_URI now means visible downtime you'll notice immediately,
    // instead of invisible data loss you might not notice for days.
    if (process.env.ALLOW_NEW_DATABASE !== "true") {
      throw new Error(
        `No existing database document found (_id="${DOC_ID}" in ${DB_NAME}.${COLLECTION_NAME}). ` +
          `If this is genuinely a brand-new site, set ALLOW_NEW_DATABASE=true in your environment once ` +
          `and redeploy to initialize it. If this site was already live, DO NOT set that — your MONGODB_URI ` +
          `is most likely pointing at the wrong cluster/database right now. Check it in your hosting ` +
          `environment variables and fix it before restarting; your real data is very likely still intact ` +
          `in the correct database, just not the one this URI currently points to.`,
      );
    }
    cachedData = JSON.parse(JSON.stringify(defaultDatabase));
    await productsStore.migrateLegacyProducts(cachedData.products);
    delete cachedData.products;
    await mongoCollection.insertOne({ _id: DOC_ID, ...cachedData });
    console.log("Design Makers database created in MongoDB (first run, ALLOW_NEW_DATABASE=true).");
  }

  // Products always load from their own dedicated collection now — this
  // is the single source of truth for the in-memory `cachedData.products`
  // array that the rest of the app reads/writes exactly as before.
  cachedData.products = await productsStore.loadAllProducts();
  console.log(`Loaded ${cachedData.products.length} product(s) from the 'products' collection.`);
  // Baseline the fingerprint against what we just loaded, so the first
  // writeDatabase() call after boot doesn't re-save an unchanged catalog.
  lastSavedProductsFingerprint = fingerprintProducts(cachedData.products);

  ensureShape(cachedData);
}

// Self-heal: older databases won't have these fields yet.
function ensureShape(database) {
  let needsUpgrade = false;
  if (!Array.isArray(database.giftCodes)) { database.giftCodes = []; needsUpgrade = true; }

  if (!Array.isArray(database.customers)) {
    database.customers = [];
    needsUpgrade = true;
  }
  // Older customer records (or ones created before Google login existed)
  // won't have the seller/role fields yet — backfill sane defaults.
  if (!Array.isArray(database.marketingCampaigns)) {
    database.marketingCampaigns = [];
    needsUpgrade = true;
  }

  database.customers.forEach((c) => {
    if (typeof c.marketingOptIn !== "boolean") {
      c.marketingOptIn = true;
      needsUpgrade = true;
    }
    if (!c.role) {
      c.role = "customer";
      needsUpgrade = true;
    }
    if (!c.sellerStatus) {
      c.sellerStatus = "none";
      needsUpgrade = true;
    }
    if (typeof c.shopTitle !== "string") {
      c.shopTitle = "";
      needsUpgrade = true;
    }
  });

  if (!Array.isArray(database.reviews)) {
    database.reviews = [];
    needsUpgrade = true;
  }

  // Back-in-stock "Notify Me" subscriptions — see server.js's
  // deliverBackInStockNotifications() for where these get acted on.
  if (!Array.isArray(database.backInStockSubscriptions)) {
    database.backInStockSubscriptions = [];
    needsUpgrade = true;
  }

  // Lightweight internal callback requests. Customers submit a reason,
  // admins are notified, and the customer is connected to the existing
  // Design Makers WhatsApp destination. No direct calling is performed.
  if (!Array.isArray(database.callbackRequests)) {
    const legacy = Array.isArray(database.callRequests) ? database.callRequests : [];
    database.callbackRequests = legacy.map((r) => ({
      id: r.id,
      requestId: `CR-${String(r.id).padStart(6, "0")}`,
      customerId: r.customerId,
      name: r.name || "",
      phone: r.phone || "",
      orderId: r.orderId || null,
      orderNumber: r.orderNumber || null,
      reason: r.reason || "",
      source: "WhatsApp",
      status: r.status === "resolved" ? "Completed" : "New",
      createdAt: r.createdAt || new Date().toISOString(),
      updatedAt: r.updatedAt || r.createdAt || new Date().toISOString(),
      completedAt: r.resolvedAt || null,
      readBy: [],
    }));
    needsUpgrade = true;
  }
  if (Object.prototype.hasOwnProperty.call(database, "callRequests")) {
    delete database.callRequests;
    needsUpgrade = true;
  }

  if (!Array.isArray(database.sellerApplications)) {
    database.sellerApplications = [];
    needsUpgrade = true;
  }

  if (!Array.isArray(database.sellers)) {
    database.sellers = [];
    needsUpgrade = true;
  }

  if (!Array.isArray(database.sellerPasswordResetRequests)) {
    database.sellerPasswordResetRequests = [];
    needsUpgrade = true;
  }

  if (!Array.isArray(database.sellerProfileUpdateRequests)) {
    database.sellerProfileUpdateRequests = [];
    needsUpgrade = true;
  }

  if (!database.settings) {
    database.settings = {};
    needsUpgrade = true;
  }

  if (!database.settings.rewards) {
    database.settings.rewards = {
      enabled: false,
      earnPerRupee: 0.01,
      redeemRate: 0.1,
      minRedeemPoints: 500,
      maxRedeemPerOrder: 500,
      pointsPerHundredSpent: 1,
      redeemPoints: 500,
      redeemValue: 50,
    };
    needsUpgrade = true;
  } else if (database.settings.rewards.maxRedeemPerOrder == null) {
    database.settings.rewards.maxRedeemPerOrder = database.settings.rewards.minRedeemPoints || 0;
    needsUpgrade = true;
  }

  if (!database.settings.saleBanner) {
    database.settings.saleBanner = { enabled: false, text: "" };
    needsUpgrade = true;
  }

  const VALID_THEMES = ["normal", "rakshabandhan"];
  if (!Object.prototype.hasOwnProperty.call(database.settings, "heroProductId")) {
    database.settings.heroProductId = null;
    needsUpgrade = true;
  }
  if (!VALID_THEMES.includes(database.settings.theme)) {
    database.settings.theme = "normal";
    needsUpgrade = true;
  }

  if (!Array.isArray(database.admins)) {
    database.admins = [];
    needsUpgrade = true;
  }

  if (!Array.isArray(database.loginHistory)) {
    database.loginHistory = [];
    needsUpgrade = true;
  }

  if (!database.activeSessions || typeof database.activeSessions !== "object") {
    database.activeSessions = {};
    needsUpgrade = true;
  }

  if (!Array.isArray(database.productViews)) {
    database.productViews = [];
    needsUpgrade = true;
  }

  // Testing/demo seller account — logs in on the seller dashboard with
  // Seller ID "seller" and password "seller", with the exact same access
  // as any other approved seller (same requireSeller middleware, same
  // dashboard). Seeded once here so it exists after any deploy, on any
  // environment, without a manual DB step.
  if (!(database.sellers || []).some((s) => s.sellerId === "seller")) {
    database.sellers.push({
      id: getNextId(database.sellers),
      sellerId: "seller",
      passwordHash: bcrypt.hashSync("seller", 10),
      name: "Demo Seller",
      email: "omgom.x@gmail.com",
      phone: "0000000000",
      altPhone: "",
      shopTitle: "Demo Shop (Testing)",
      businessType: "",
      businessAddress: "",
      city: "",
      state: "",
      pincode: "",
      aadhaarLast4: "",
      aadhaarFull: "",
      panNumber: "",
      dob: "",
      gender: "",
      bankAccountNumber: "",
      ifscCode: "",
      upiId: "",
      gstNumber: "",
      notes: "Demo/testing account — not a real seller.",
      applicationId: null,
      createdAt: new Date().toISOString(),
      banned: false,
      mustChangePassword: false,
    });
    needsUpgrade = true;
  }

  // Self-heal the demo account every time the database is read — not just
  // once at seed time. Admin actions like "Reset password" or an accidental
  // ban touch this record just like any other seller's, which used to leave
  // the demo account stuck on a forced password-change screen or otherwise
  // unable to log in. The demo account should always be free to log straight
  // in with "seller" / "seller", and should always use the test inbox
  // (omgom.x@gmail.com) so order-notification emails can actually be
  // checked while testing.
  const demoSeller = (database.sellers || []).find((s) => s.sellerId === "seller");
  if (demoSeller) {
    if (demoSeller.mustChangePassword) {
      delete demoSeller.mustChangePassword;
      needsUpgrade = true;
    }
    if (demoSeller.banned) {
      demoSeller.banned = false;
      needsUpgrade = true;
    }
    if (demoSeller.email !== "omgom.x@gmail.com") {
      demoSeller.email = "omgom.x@gmail.com";
      needsUpgrade = true;
    }
  }

  // Inventory migration: every product gets a unique internal product code
  // and mandatory stock fields. Existing products are kept sellable until the
  // admin performs the first inventory import, so this deploy cannot suddenly
  // make the live catalog unavailable. New products start at 0 stock.
  const productPrefix = (category) => {
    const c = String(category || "").toLowerCase();
    if (c.includes("t-shirt") || c.includes("tshirt") || c.includes("tee")) return "TS";
    if (c.includes("mug")) return "MUG";
    if (c.includes("frame")) return "FRM";
    if (c.includes("cushion")) return "CUS";
    if (c.includes("keychain") || c.includes("key chain")) return "KEY";
    if (c.includes("bottle")) return "BOT";
    if (c.includes("cover") || c.includes("phone")) return "COV";
    return (c.replace(/[^a-z0-9]/g, "").slice(0, 3).toUpperCase() || "PRD");
  };
  const usedCodes = new Set((database.products || []).map((p) => p.productCode).filter(Boolean));
  const counters = {};
  (database.products || []).forEach((p) => {
    if (!p.isGiftAddon && !p.productCode) {
      const prefix = productPrefix(p.category);
      counters[prefix] = counters[prefix] || 0;
      let code;
      do { counters[prefix] += 1; code = `DM-${prefix}-${String(counters[prefix]).padStart(3, "0")}`; } while (usedCodes.has(code));
      p.productCode = code;
      usedCodes.add(code);
      needsUpgrade = true;
    }
    if (!p.isGiftAddon && p.stockQty === undefined) { p.stockQty = 999999; p.stockConfigured = false; needsUpgrade = true; }
    if (!p.isGiftAddon && p.lowStockThreshold === undefined) { p.lowStockThreshold = 5; needsUpgrade = true; }
    if (!p.isGiftAddon && (!p.variantStock || typeof p.variantStock !== "object")) { p.variantStock = {}; needsUpgrade = true; }
    if (!p.isGiftAddon && (!p.variantStockConfigured || typeof p.variantStockConfigured !== "object")) {
      p.variantStockConfigured = {};
      if (p.stockConfigured !== false && Array.isArray(p.sizes)) {
        p.sizes.forEach((size) => { if (Object.prototype.hasOwnProperty.call(p.variantStock, size)) p.variantStockConfigured[size] = true; });
      }
      needsUpgrade = true;
    }
  });

  // Backfill the gift add-on product for databases that existed before
  // this feature was added, so the offer works without a manual admin step.
  if (Array.isArray(database.products) && !database.products.some((p) => p.id === GIFT_ADDON.productId)) {
    database.products.push({
      id: GIFT_ADDON.productId,
      name: GIFT_ADDON.name,
      category: "Gift Addon",
      description: "A printed photo mug, added to your order as a limited-time extra.",
      price: GIFT_ADDON.price,
      image: "",
      active: true,
      hidden: true,
      isGiftAddon: true,
      customizationEnabled: false,
      sizes: [],
      moq: 1,
      discounts: [],
      options: {},
    });
    needsUpgrade = true;
  }

  // Orders created before paymentStatus existed — backfill so old orders
  // don't break the admin UI or the mark-paid endpoint. Treated as
  // "pending" since there's no reliable way to know which of them were
  // actually confirmed on WhatsApp.
  if (Array.isArray(database.orders)) {
    const usedOrderNumbers = new Set(database.orders.map((o) => String(o.orderNumber || "")).filter(Boolean));
    let orderFallbackCounter = 10000000;
    const nextLegacyOrderNumber = () => {
      let candidate;
      do {
        orderFallbackCounter += 1;
        if (orderFallbackCounter > 99999999) orderFallbackCounter = 10000001;
        candidate = `DM-${String(orderFallbackCounter).padStart(8, "0")}`;
      } while (usedOrderNumbers.has(candidate));
      usedOrderNumbers.add(candidate);
      return candidate;
    };

    database.orders.forEach((o) => {
      // Customer-facing Order ID is permanent. Older orders that predate the
      // Order ID feature receive one once and it is never regenerated later.
      if (!o.orderNumber) {
        o.orderNumber = nextLegacyOrderNumber();
        needsUpgrade = true;
      }
      if (!o.paymentStatus) {
        o.paymentStatus = "pending";
        needsUpgrade = true;
      }
      if (o.paidAt === undefined) {
        o.paidAt = null;
        needsUpgrade = true;
      }
      if (!Array.isArray(o.statusHistory)) {
        o.statusHistory = [{ status: o.status || "New", at: o.createdAt || new Date().toISOString() }];
        needsUpgrade = true;
      }
      if (o.inventoryDeducted === undefined) { o.inventoryDeducted = false; needsUpgrade = true; }
      if (o.inventoryRestored === undefined) { o.inventoryRestored = false; needsUpgrade = true; }
    });
  }

  return needsUpgrade;
}

// Read database (synchronous — served from the in-memory cache that
// connectDB() populated at startup).
function readDatabase() {
  if (!cachedData) {
    throw new Error("Database not initialized yet. Call connectDB() before handling requests.");
  }
  if (ensureShape(cachedData)) {
    writeDatabase(cachedData);
  }
  return cachedData;
}

// Save database — updates the in-memory cache immediately (so the next
// readDatabase() sees the change right away) and persists to MongoDB
// in the background.
//
// Products are split out and saved to their own `products` collection
// (one document per product, via products-store.js) instead of being
// embedded in the single app_data document — that embedding is what
// previously let app_data grow past MongoDB's 16MB limit and start
// silently failing to save as the catalog (and its photos) grew.
function writeDatabase(data) {
  cachedData = data;
  const { products, ...restOfData } = data;

  // writeDatabase() is called from ~90 places across the app (order
  // placement, gift-code toggles, settings changes, seller password
  // resets — almost anything). Most of those never touch the products
  // array at all, so we only re-save the products collection (bulkWrite +
  // deleteMany over every product, incl. base64 photos) when something
  // about the products actually changed since the last successful save.
  // Everything is queued through writeQueue so writes to Mongo always
  // complete in the same order they were requested in.
  const fingerprint = fingerprintProducts(products);
  const productsChanged = fingerprint !== lastSavedProductsFingerprint;

  writeQueue = writeQueue.then(async () => {
    if (mongoCollection) {
      try {
        await mongoCollection.replaceOne({ _id: DOC_ID }, { _id: DOC_ID, ...restOfData }, { upsert: true });
      } catch (err) {
        console.error("Failed to persist database to MongoDB:", err.message);
      }
    }

    if (productsChanged) {
      try {
        await productsStore.saveAllProducts(products || []);
        lastSavedProductsFingerprint = fingerprint;
      } catch (err) {
        console.error("Failed to persist products to MongoDB:", err.message);
        // Leave lastSavedProductsFingerprint unchanged so the NEXT
        // writeDatabase() call retries this save instead of wrongly
        // treating it as already-saved.
      }
    }
  });
  // Never let one failed write silently kill the whole chain for every
  // write that comes after it.
  writeQueue = writeQueue.catch((err) => {
    console.error("Unexpected error in database write queue:", err.message);
  });

  return data;
}

// Generate next ID
function getNextId(items) {
  if (!items.length) {
    return 1;
  }
  return Math.max(...items.map((item) => item.id)) + 1;
}

module.exports = {
  connectDB,
  readDatabase,
  writeDatabase,
  getNextId,
  GIFT_ADDON,
};
